"""Source-reviewed municipal and SCC records, plus errata coverage."""
import pathlib,json
out=pathlib.Path(__file__).resolve().parent
notes=json.loads((out/'reviewed-notes.json').read_text())
def put(id,title,typ,edition,date,summary,scope,conditions,cites,topics,**extra):
 notes[id]=dict(title=title,type=typ,code_edition=edition,date=date,summary=summary,applies_to=scope,conditions=conditions.split('|'),selected_citations=cites.split(),topics=topics.split(),conditions_completeness='Source navigation summary; read every operative condition and applicable diagram in the original document.',**extra)
 (out/'reviewed-notes.json').write_text(json.dumps(notes,indent=2,ensure_ascii=False)+'\n')
put('calgary-spv-001-zero-lot-line-2026-03','SPV-001 – Zero Lot Line (Revision 5)','spv','NBC(AE), edition not explicitly numbered in PDF; current Calgary posting','2026-03-05','Provides a permit-referenced, paired-house construction package for qualifying Calgary zero-lot-line homes.','Calgary single-family houses up to three storeys, including houses with secondary suites, within the SPV configuration.','Reference SPV-001 in application documents and permit conditions; no deviations are permitted.|Coordinate both adjacent buildings and register the required maintenance/access easement on both titles.|Apply the complete gypsum, cladding, soffit, opening, balcony, separation and construction details.|SOURCE CONFLICT: page 4 lists maximum footing projection as 0.3 m while page 5 authority/conditions text says 0.6 m. Obtain Calgary clarification; this index does not resolve that inconsistency.','B:9.10.15.5.(8) B:9.10.15.5.(9)','fire-separations-and-spatial-separation housing-secondary-suites-part9 process-and-admin',source_conflicts=[{'source_pdf_pages':[4,5],'issue':'Footing projection into easement: 0.3 m versus 0.6 m.','resolution':'UNVERIFIED: requires issuer clarification; do not silently choose either value.'}])
put('calgary-spv-003-construction-of-exposed-building-face','SPV-003 – Construction of Exposed Building Face (Revision 3)','spv','NBC(AE), edition not explicitly numbered in PDF; current Calgary posting','2025-02-12','Accepts a specified encapsulated wood-frame exposed-wall assembly for qualifying single-storey F3 Part 9 buildings facing dwellings they do not serve.','Calgary F3 accessory/garage-type buildings and facing multidwelling buildings in the stated spatial-separation situation.','Reference SPV-003 in permit documents and conditions; no deviations.|Use the entire specified encapsulation, exterior cladding, framing, sheathing/joint and roof/soffit package.|Use the document’s exposing-face and limiting-distance treatment only within its scope.','B:9.10.14.2. B:9.10.14.5.(1)','fire-separations-and-spatial-separation combustible-construction-and-mass-timber building-envelope-insulation-cladding')
put('calgary-spv-006-firewall-rowhouse-secondary-suites','SPV-006 – Firewall in a Rowhouse with Secondary Suites','spv','NBC(AE), edition not explicitly numbered in PDF; current Calgary posting','2025-06-19','Accepts a package of compartmentation, egress and service protections instead of the prescribed firewall in qualifying rowhouses with secondary suites.','Calgary rowhouses containing more than two houses with secondary suites.','Reference SPV-006 in the application and permit conditions; no deviations.|Provide the required suite/exit fire separations and support ratings, using only the stated sprinkler alternatives.|Apply the separate-egress alternatives, protected doors/penetrations and qualifying noncombustible duct provisions.|Submit HVAC drawings; an individualized variance outside this SPV needs professional involvement.','B:9.10.11.2.(2) B:9.10.13.13.(1)','fire-separations-and-spatial-separation housing-secondary-suites-part9 egress-and-single-stair hvac-ventilation-plumbing professional-involvement')
put('calgary-new-standing-posted-variance-procedure','New Standing Posted Variance Procedure','bulletin','ABC 2014','2017-09-06','Explains the move from repeated individual zero-lot-line variance requests to a referenced standing posted variance.','Calgary applicants using an unmodified applicable SPV.','State compliance with the applicable SPV in permit documents or a supporting letter.|Permit must reference the SPV and all of its conditions.|The historical zero-lot-line procedure excludes inner-city/infill use; read current SPV scope directly.','B:9.10.15.5.(8)','process-and-admin fire-separations-and-spatial-separation',historical_counts={'builders':26,'requests':382,'period':'2017-01-01 to 2017-09-01 as stated by the advisory; not a current provincewide statistic'})
put('calgary-plumbing-advisory-p15-002-secondary-suites-backwater-valves','P15-002 – Secondary Suites, Backwater Valves and Protection from Backflow','bulletin','National Plumbing Code 2020','2022-10-04','Explains backflow protection for secondary suites and the restriction on a normally open valve serving multiple dwelling units.','Calgary secondary-suite plumbing installations exposed to sewage backflow.','Assess whether below-street-level fixtures need protection.|A normally open backwater valve on the identified drain/branch cannot serve more than one dwelling unit under this advisory.|Existing multi-unit arrangements may need removal/reconfiguration/additional protection.|This is a plumbing advisory, not an SPV or a verified NBC provision.','PLUMBING:2.4.6.4.','hvac-ventilation-plumbing housing-secondary-suites-part9')
